package fk.sp.enricher.resource.handlers;

import com.google.inject.Inject;
import com.google.inject.Singleton;
import fk.sp.enricher.common.config.CommonConstants;
import fk.sp.enricher.common.exceptions.HeaderNotFoundException;
import fk.sp.enricher.common.exceptions.InvalidViewException;
import fk.sp.enricher.core.common.BaseRequest;
import fk.sp.enricher.resource.core.EnricherService;
import fk.sp.enricher.resource.model.Views;
import fk.sp.enricher.resource.subscribers.ListingsEnricherJsonResponseSubscriber;
import fk.sp.enricher.resource.support.VertxBaseRequestBuilder;
import fk.sp.enricher.resource.utils.HeaderUtils;
import io.vertx.core.Handler;
import io.vertx.core.MultiMap;
import io.vertx.core.buffer.Buffer;
import io.vertx.ext.web.RoutingContext;
import lombok.extern.slf4j.Slf4j;
import org.slf4j.MDC;

import java.util.List;
import java.util.UUID;

/\*\*
 \* The route handler for enrichment.
 \*/
@Slf4j
@Singleton
public class EnrichmentRouteHandler implements Handler {

 private final Views views;
 private final EnricherService enricherService;

 @Inject
 public EnrichmentRouteHandler(final Views views,
 final EnricherService enricherService) {
 this.views = views;
 this.enricherService = enricherService;
 }

 @Override
 public void handle(RoutingContext event) {
 final String viewId = getHeader(event.request().headers(), HeaderUtils.VIEW\_ID\_HEADERS);
 final String clientId = getHeader(event.request().headers(), HeaderUtils.CLIENT\_ID\_HEADERS);
 log.debug("Got a new request for view:{} from client:{}!", viewId, clientId);
 validateView(viewId);

 event.request().bodyHandler(bodyHandler(event, viewId, clientId)).exceptionHandler(FailureHandler.from(event));
 }

 private Handler bodyHandler(final RoutingContext event, final String viewId, final String clientId) {

 return bodyBuffer -> {
 final BaseRequest incomingRequest = VertxBaseRequestBuilder.builder()
 .path(event.request().path())
 .viewId(viewId)
 .queryParams(event.request().params())
 .headers(event.request().headers())
 .body(bodyBuffer.toString())
 .clientId(clientId)
 .build().get();

 updateMDC(event.request().headers(), incomingRequest);

 enricherService.apply(incomingRequest).subscribe(new ListingsEnricherJsonResponseSubscriber<>(event));
 };
 }

 private String getHeader(final MultiMap headers, List possibleHeaderNames) {
 return HeaderUtils.getHeader(headers, possibleHeaderNames)
 .orElseThrow(() -> new HeaderNotFoundException(possibleHeaderNames.iterator().next()));
 }

 private void updateMDC(final MultiMap headers, final BaseRequest incomingRequest) {
 final String transactionId = HeaderUtils.getHeader(headers, HeaderUtils.TRANSACTION\_ID\_HEADERS).orElseGet(() -> String.format("TXN-%s", UUID.randomUUID()));
 final String requestId = String.format("REQ-%s", UUID.randomUUID());
 MDC.put(CommonConstants.REQUEST\_ID, requestId);
 MDC.put(CommonConstants.TRANSACTION\_ID, transactionId);

 incomingRequest.setRequestId(requestId);
 incomingRequest.setTransactionId(transactionId);
 }

 private void validateView(String viewId) {
 if (!views.isValidViewName(viewId)) {
 throw new InvalidViewException(viewId);
 }
 }
}

